export class GameEffects {
  constructor(stage,enabled){this.stage=stage;this.enabled=enabled;this.reduced=matchMedia('(prefers-reduced-motion: reduce)');this.animations=[];this.timers=[];this.raf=0;this.canvas=document.createElement('canvas');this.canvas.className='celebration-canvas';this.canvas.setAttribute('aria-hidden','true');document.body.append(this.canvas);this.ctx=this.canvas.getContext('2d');this.reduced.addEventListener('change',()=>this.clear());}
  get motion(){return this.enabled()&&!this.reduced.matches;}
  clear(){this.animations.forEach(a=>a.cancel());this.animations=[];this.timers.forEach(clearTimeout);this.timers=[];cancelAnimationFrame(this.raf);this.raf=0;this.ctx.clearRect(0,0,this.canvas.width,this.canvas.height);this.stage.querySelectorAll('.move-ripple,.capture-flash,.impact-caption').forEach(el=>el.remove());}
  move(event,is3d){if(!event||!this.motion)return;const cell=document.querySelector(event.to?`[data-square="${event.to}"]`:`.board-cell[data-r="${event.r}"][data-c="${event.c}"]`);if(!is3d&&cell){const content=cell.querySelector('.stone,.chess-piece,.xiangqi-piece,.jungle-piece');if(content)this.animations.push(event.dropRows?content.animate([{translate:`0 ${-119*event.dropRows}%`},{translate:'0 0',offset:.72,easing:'ease-out'},{translate:'0 -12%',offset:.86,easing:'ease-in'},{translate:'0 0'}],{duration:260+event.dropRows*50,easing:'ease-in'}):content.animate([{translate:'0 -16px',opacity:.25,scale:'.85'},{translate:'0 1px',opacity:1,scale:'1.08'},{translate:'0 0',scale:'1'}],{duration:350,easing:'cubic-bezier(.2,.8,.2,1)'}));const ripple=document.createElement('span');ripple.className='move-ripple';cell.append(ripple);this.timers.push(setTimeout(()=>ripple.remove(),650));}
    if(event.capture||event.flips){this.impact(is3d,event.capture?'吃子 · 好手':`翻转 ${event.flips} 子`,event.capture?1:.55);}
  }
  impact(is3d,label='吃子 · 好手',strength=1){if(!this.motion)return;const target=is3d?document.querySelector('#board-3d'):document.querySelector('#board-frame');this.animations.push(target.animate([{translate:'0 0'},{translate:`${-7*strength}px ${3*strength}px`},{translate:`${6*strength}px ${-4*strength}px`},{translate:`${-4*strength}px ${2*strength}px`},{translate:`${2*strength}px 0`},{translate:'0 0'}],{duration:370,easing:'ease-out'}));const flash=document.createElement('span');flash.className='capture-flash';this.stage.append(flash);const caption=document.createElement('span');caption.className='impact-caption';caption.textContent=label;this.stage.append(caption);this.timers.push(setTimeout(()=>{flash.remove();caption.remove();},950));}
  confetti(){if(!this.motion)return;cancelAnimationFrame(this.raf);const width=innerWidth,height=innerHeight,ratio=Math.min(devicePixelRatio,1.5);this.canvas.width=width*ratio;this.canvas.height=height*ratio;this.ctx.setTransform(ratio,0,0,ratio,0,0);const colors=['#bb613e','#c5a35c','#829770','#e2cf9c','#f2e5c3'];const pieces=Array.from({length:100},(_,i)=>({x:width/2,y:height*.35,vx:(Math.random()-.5)*width*.9,vy:-height*(.15+Math.random()*.55),size:4+Math.random()*6,spin:Math.random()*6,color:colors[i%colors.length],shape:i%5===0}));const start=performance.now();const frame=now=>{const t=(now-start)/1000;this.ctx.clearRect(0,0,width,height);this.ctx.globalAlpha=Math.min(1,(4.5-t)*1.5);for(const p of pieces){const x=p.x+p.vx*t*.6,y=p.y+p.vy*t+height*.26*t*t;if(y>height+20)continue;this.ctx.save();this.ctx.translate(x,y);this.ctx.rotate(p.spin+t*3);this.ctx.fillStyle=p.color;if(p.shape){this.ctx.beginPath();this.ctx.arc(0,0,p.size/2,0,Math.PI*2);this.ctx.fill();}else this.ctx.fillRect(-p.size/2,-p.size/2,p.size,Math.max(2,p.size*Math.cos(t*5+p.spin)));this.ctx.restore();}this.ctx.globalAlpha=1;if(t<4.5)this.raf=requestAnimationFrame(frame);else{this.ctx.clearRect(0,0,width,height);this.raf=0;}};this.raf=requestAnimationFrame(frame);}
}
